{"content": "1|// FairFahren game server: serves the static game exactly like `npm start`, and
2|// later speaks WebSocket on /ws for the multiplayer race (phase 2 wires the
3|// game rules in). Usage: node server/main.mjs [port]   (default 8080)
4|import { createServer } from 'node:http';
5|import { resolve } from 'node:path';
6|import { fileURLToPath } from 'node:url';
7|import { serveStatic } from './static.mjs';
8|import { acceptConnection } from './ws.js';
9|
10|const ROOT = resolve(fileURLToPath(new URL('..', import.meta.url)));
11|
12|// Composes the game server. `onConnect(conn)` receives every accepted
13|// WebSocket connection: { send(text), close(code, reason), onMessage(cb), onClose(cb) }.
14|export function createGameServer({ onConnect } = {}) {
15|  const server = createServer(serveStatic(ROOT));
16|  const connections = new Set();
17|  server.on('upgrade', (req, socket) => {
18|    if (new URL(req.url, 'http://x').pathname !== '/ws') return socket.destroy();
19|    const conn = acceptConnection(socket, req.headers);
20|    if (!conn) return; // invalid handshake: already answered and destroyed
21|    connections.add(conn);
22|    conn.onClose(() => connections.delete(conn));
23|    onConnect?.(conn);
24|  });
25|  return { server, connections };
26|}
27|
28|if (import.meta.main) {
29|  const PORT = Number(process.argv[2] ?? process.env.PORT ?? 8080);
30|  // 0.0.0.0: reachable from other machines on the intranet, not just localhost.
31|  createGameServer().server.listen(PORT, '0.0.0.0', () =>
32|    console.log(`FairFahren server on http://0.0.0.0:${PORT} (game + WebSocket /ws)`));
33|}", "total_lines": 33, "file_size": 1527, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// RFC 6455 WebSocket, hand-rolled on the raw socket node:http hands us from the
2|// 'upgrade' event. Pure, byte-level pieces (handshake, framing, masking) that
3|// the unit tests can drive with Buffers. Scope: small unfragmented frames only
4|// (this is a LAN game with tiny JSON messages), so no fragmentation/extensions.
5|import { createHash } from 'node:crypto';
6|
7|export const GUID = '258EAFA5-E914-47DA-95CA-C5AB0DC85B11';
8|export const OP = { text: 0x1, close: 0x8, ping: 0x9, pong: 0xa };
9|export const MAX_PAYLOAD = 65535; // frames above this are rejected (small frames only)
10|
11|// --- Handshake ---
12|
13|// RFC 6455 §4.2.2: base64(SHA-1(key + GUID)).
14|export function acceptKey(key) {
15|  return createHash('sha1').update(key + GUID).digest('base64');
16|}
17|
18|const KEY_RE = /^[A-Za-z0-9+/]{22}==$/; // base64 of the required 16 random bytes
19|
20|// Validate the headers of an upgrade request (node:http lowercases them).
21|// Returns { ok: true, key } or { ok: false, status, reason, extra }.
22|export function validateUpgrade(h) {
23|  if (!h || h.upgrade?.toLowerCase() !== 'websocket')
24|    return { ok: false, status: 400, reason: 'Bad Request' };
25|  const tokens = (h.connection ?? '').toLowerCase().split(',').map((s) => s.trim());
26|  if (!tokens.includes('upgrade'))
27|    return { ok: false, status: 400, reason: 'Bad Request' };
28|  if (h['sec-websocket-version'] !== '13')
29|    return { ok: false, status: 426, reason: 'Upgrade Required', extra: 'Sec-WebSocket-Version: 13\r\n' };
30|  const key = h['sec-websocket-key'];
31|  if (typeof key !== 'string' || !KEY_RE.test(key))
32|    return { ok: false, status: 400, reason: 'Bad Request' };
33|  return { ok: true, key };
34|}
35|
36|// The full 101 reply that switches the HTTP connection into WebSocket mode.
37|export function handshakeResponse(key) {
38|  return `HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ${acceptKey(key)}\r\n\r\n`;
39|}
40|
41|// --- Framing ---
42|
43|// XOR the payload with the 4 mask bytes, in place (symmetric: mask twice = original).
44|export function applyMask(data, mask) {
45|  for (let i = 0; i < data.length; i++) data[i] ^= mask[i & 3];
46|  return data;
47|}
48|
49|// Encode one unmasked server frame (server frames are never masked, RFC §5.1).
50|export function encodeFrame(opcode, payload = '') {
51|  const data = typeof payload === 'string' ? Buffer.from(payload, 'utf8') : Buffer.from(payload);
52|  if (data.length > MAX_PAYLOAD) throw new Error('ws: frame too large');
53|  if (opcode > 7 && data.length > 125) throw new Error('ws: control frame payload > 125');
54|  const head = data.length < 126 ? Buffer.from([0x80 | opcode, data.length]) : Buffer.alloc(4);
55|  if (head.length === 4) { // 126..65535 bytes: 16-bit extended length
56|    head[0] = 0x80 | opcode; head[1] = 126; head.writeUInt16BE(data.length, 2);
57|  }
58|  return Buffer.concat([head, data]);
59|}
60|
61|const KNOWN_OPCODES = new Set([0x1, 0x2, 0x8, 0x9, 0xa]);
62|
63|// Try to decode ONE frame from the front of `buf`. Returns null while more bytes
64|// are needed; otherwise { fin, opcode, masked, payload, bytes } with the payload
65|// unmasked and copied (the caller keeps `buf`) and `bytes` = total frame size.
66|// Throws on protocol violations (reserved bits, fragments, oversized control frames).
67|export function decodeFrame(buf) {
68|  if (buf.length < 2) return null;
69|  const fin = (buf[0] & 0x80) !== 0, rsv = buf[0] & 0x70, opcode = buf[0] & 0x0f;
70|  const masked = (buf[1] & 0x80) !== 0;
71|  let len = buf[1] & 0x7f, off = 2;
72|  if (rsv !== 0) throw new Error('ws: reserved bits set');
73|  if (!KNOWN_OPCODES.has(opcode)) throw new Error('ws: reserved opcode');
74|  if (!fin) throw new Error('ws: fragmented frames not supported');
75|  if (len === 127) throw new Error('ws: 64-bit frame lengths not supported');
76|  if (len === 126) {
77|    if (buf.length < 4) return null;
78|    len = buf.readUInt16BE(2); off = 4;
79|  }
80|  if (opcode > 7 && len > 125) throw new Error('ws: control frame payload > 125');
81|  if (masked && buf.length < off + 4) return null;
82|  const mask = masked ? buf.subarray(off, off + 4) : null;
83|  if (masked) off += 4;
84|  if (buf.length < off + len) return null;
85|  const payload = Buffer.from(buf.subarray(off, off + len));
86|  if (mask) applyMask(payload, mask);
87|  return { fin, opcode, masked, payload, bytes: off + len };
88|}
89|
90|// Incremental reader for a stream: pass it arbitrary chunks, it emits complete
91|// frames via `onFrame` in arrival order and lets protocol errors propagate.
92|export function createFrameReader(onFrame) {
93|  let buf = null;
94|  return (chunk) => {
95|    buf = buf ? Buffer.concat([buf, chunk]) : Buffer.from(chunk);
96|    for (;;) {
97|      if (!buf) return;
98|      const f = decodeFrame(buf);
99|      if (!f) return;
100|      buf = f.bytes < buf.length ? buf.subarray(f.bytes) : null;
101|      onFrame(f);
102|    }
103|  };
104|}
105|
106|// --- Connection: one live WebSocket over an upgraded socket ---
107|
108|// 2-byte close code + optional utf8 reason (control payload limit: 125 bytes).
109|function closePayload(code, reason) {
110|  const r = Buffer.from(String(reason ?? ''), 'utf8').subarray(0, 123);
111|  return Buffer.concat([Buffer.from([code >> 8, code & 0xff]), r]);
112|}
113|
114|// Validate the upgrade, write the 101 reply, wrap the socket. Returns a
115|// WsConnection, or null after answering + closing an invalid handshake.
116|// (socket.end, never destroy-after-write: destroy discards unflushed bytes.)
117|export function acceptConnection(socket, headers) {
118|  const v = validateUpgrade(headers);
119|  if (!v.ok) {
120|    socket.on('error', () => {});
121|    socket.end(`HTTP/1.1 ${v.status} ${v.reason}\r\n${v.extra ?? ''}Connection: close\r\nContent-Length: 0\r\n\r\n`);
122|    return null;
123|  }
124|  socket.write(handshakeResponse(v.key));
125|  return new WsConnection(socket);
126|}
127|
128|export class WsConnection {
129|  // Text frames come out as onMessage(string); pings are answered with pongs
130|  // automatically; a close from either side ends the socket and fires onClose
131|  // exactly once. Binary frames are refused (the protocol is JSON text only).
132|  constructor(socket) {
133|    this.socket = socket;
134|    this.onMessage = null;
135|    this.onClose = null;
136|    this.open = true;
137|    this.closing = false;
138|    socket.setNoDelay(true); // latency matters more than bandwidth here
139|    const reader = createFrameReader((f) => this._onFrame(f));
140|    socket.on('data', (chunk) => { try { reader(chunk); } catch { this._close(1002, 'protocol error'); } });
141|    socket.on('error', () => {}); // socket errors surface as 'close', never a crash
142|    socket.on('close', () => this._closed());
143|  }
144|
145|  send(text) { this._send(OP.text, Buffer.from(String(text), 'utf8')); }
146|  close(code = 1000, reason = '') { this._close(code, reason); }
147|
148|  _onFrame(f) {
149|    if (f.opcode === OP.ping) return this._send(OP.pong, f.payload);
150|    if (f.opcode === OP.pong) return; // RTT is measured with app-level ping/pong messages
151|    if (f.opcode === OP.close) {
152|      const code = f.payload.length >= 2 ? f.payload.readUInt16BE(0) : 1000;
153|      return this._close(code, ''); // echo the close, then end
154|    }
155|    if (f.opcode === OP.text) return this.onMessage?.(f.payload.toString('utf8'));
156|    this._close(1003, 'binary not supported');
157|  }
158|
159|  _send(opcode, payload) {
160|    if (this.closing) return;
161|    try { this.socket.write(encodeFrame(opcode, payload)); } catch { /* socket died mid-write */ }
162|  }
163|
164|  // Send a close frame, then end the socket (end flushes; destroy would not).
165|  _close(code, reason) {
166|    if (this.closing) return;
167|    this._send(OP.close, closePayload(code, reason));
168|    this.closing = true;
169|    this.socket.end();
170|  }
171|
172|  _closed() {
173|    if (!this.open) return;
174|    this.open = false;
175|    this.onClose?.();
176|  }
177|}", "total_lines": 177, "file_size": 7577, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// The multiplayer message language: one entry per message type, declaring its
2|// direction ('cs' client → server, 'sc' server → client), its wire fields and
3|// its design rate. One shared encode/decode pair is driven by those entries,
4|// so every packet is validated against the same definitions that produce the
5|// protocol table in NOTES.md (`node tools/protocol-table.mjs`).
6|//
7|// Wire format: JSON text frames tagged with `type` — messages are tiny and the
8|// intranet is fast, so readable beats compact. All times are milliseconds in
9|// the shared server clock (clients learn their offset via ping/pong, because
10|// the browser's WebSocket API hides the protocol-level ping/pong from JS).
11|
12|export const STAGES = ['lobby', 'countdown', 'racing', 'finished', 'ceremony'];
13|export const MAX_PLAYERS = 4;
14|
15|const err = (where, why) => new Error(`protocol: ${where} ${why}`);
16|
17|// --- Field validators (used by encode AND decode, so both sides agree) ---
18|
19|function str(v, w) {
20|  if (typeof v !== 'string' || v.length < 1 || v.length > 24) throw err(w, 'must be a 1..24 char string');
21|  return v;
22|}
23|function num(v, w) {
24|  if (typeof v !== 'number' || !Number.isFinite(v)) throw err(w, 'must be a finite number');
25|  return v;
26|}
27|function idNum(v, w) {
28|  if (!Number.isInteger(v) || v < 1) throw err(w, 'must be a positive integer');
29|  return v;
30|}
31|function seedNum(v, w) {
32|  if (!Number.isInteger(v) || v < 0) throw err(w, 'must be a non-negative integer');
33|  return v;
34|}
35|function stageOf(v, w) {
36|  if (!STAGES.includes(v)) throw err(w, `must be one of ${STAGES.join('|')}`);
37|  return v;
38|}
39|function rosterOf(v, w) {
40|  if (!Array.isArray(v) || v.length > MAX_PLAYERS) throw err(w, `must be an array of at most ${MAX_PLAYERS} players`);
41|  return v.map((p, i) => {
42|    if (typeof p !== 'object' || p === null || Array.isArray(p)) throw err(`${w}[${i}]`, 'must be an object');
43|    for (const k of Object.keys(p)) if (k !== 'id' && k !== 'name') throw err(`${w}[${i}]`, `has unknown field ${k}`);
44|    if (!('id' in p) || !('name' in p)) throw err(`${w}[${i}]`, 'needs id and name');
45|    return { id: idNum(p.id, `${w}[${i}].id`), name: str(p.name, `${w}[${i}].name`) };
46|  });
47|}
48|
49|// --- The registry ---
50|
51|export const MESSAGES = {
52|  // client → server
53|  join:       { dir: 'cs', rate: 'once, on entering the lobby', fields: { name: str } },
54|  name:       { dir: 'cs', rate: 'on change, in lobby',          fields: { name: str } },
55|  start:      { dir: 'cs', rate: 'user-triggered',               fields: {} },
56|  pos:        { dir: 'cs', rate: '15 Hz while racing',           fields: { x: num, z: num, h: num, s: num } },
57|  finish:     { dir: 'cs', rate: 'once per race',                fields: { t: num } },
58|  ping:       { dir: 'cs', rate: 'about 1 Hz while syncing',     fields: { t: num } },
59|  // server → client
60|  roster:     { dir: 'sc', rate: 'on change',                    fields: { players: rosterOf, seed: seedNum } },
61|  countdown:  { dir: 'sc', rate: 'once per race',                fields: { goAt: num } },
62|  go:         { dir: 'sc', rate: 'once per race',                fields: { goAt: num } },
63|  posRelay:   { dir: 'sc', rate: 'per player, 15 Hz',            fields: { id: idNum, x: num, z: num, h: num, s: num } },
64|  stage:      { dir: 'sc', rate: 'on change',                    fields: { stage: stageOf } },
65|  disconnect: { dir: 'sc', rate: 'on player leaving',            fields: { id: idNum } },
66|  pong:       { dir: 'sc', rate: 'on ping',                      fields: { t: num, s: num } },
67|};
68|
69|// --- The encode/decode pair ---
70|
71|// encode(type, data) → JSON string, fields validated on the way out.
72|export function encode(type, data) {
73|  const def = MESSAGES[type];
74|  if (!def) throw err(type, 'is not a known message type');
75|  const out = { type };
76|  for (const [f, check] of Object.entries(def.fields)) out[f] = check(data?.[f], `${type}.${f}`);
77|  return JSON.stringify(out);
78|}
79|
80|// decode(text) → { type, data }, or throws on anything unknown or malformed:
81|// bad JSON, non-objects, unknown types, missing/unknown fields, wrong value types.
82|export function decode(text) {
83|  let m = null;
84|  try { m = JSON.parse(text); } catch { /* handled below */ }
85|  if (typeof m !== 'object' || m === null || Array.isArray(m)) throw err('packet', 'must be a JSON object');
86|  const def = MESSAGES[m.type];
87|  if (!def) throw err('packet', `unknown message type ${JSON.stringify(m.type)}`);
88|  const known = Object.keys(def.fields);
89|  for (const k of Object.keys(m)) if (k !== 'type' && !known.includes(k)) throw err(m.type, `unknown field ${k}`);
90|  const data = {};
91|  for (const [f, check] of Object.entries(def.fields)) data[f] = check(m[f], `${m.type}.${f}`);
92|  return { type: m.type, data };
93|}
94|
95|// Markdown table of the whole protocol, generated from the registry. NOTES.md
96|// embeds it between markers; a test keeps the two from drifting apart.
97|export function protocolTable() {
98|  const rows = Object.entries(MESSAGES).map(([name, d]) =>
99|    `| ${name} | ${d.dir === 'cs' ? 'client → server' : 'server → client'} | ${Object.keys(d.fields).join(' ') || '—'} | ${d.rate} |`);
100|  return ['| type | from | fields | rate |', '|---|---|---|---|', ...rows].join('\n');
101|}", "total_lines": 101, "file_size": 5180, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// Static file serving, shared by the dev server (tools/serve.mjs) and the game
2|// server (server/main.mjs) — one implementation, no copy-paste. Extracted from
3|// tools/serve.mjs; the try/catch around path parsing is new: a malformed URL
4|// (e.g. "/%") must answer 400, not crash the process with an unhandled throw.
5|import { readFile } from 'node:fs/promises';
6|import { extname, join, normalize, sep } from 'node:path';
7|
8|const TYPES = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.mjs': 'text/javascript; charset=utf-8', '.css': 'text/css', '.json': 'application/json', '.md': 'text/markdown; charset=utf-8' };
9|
10|// Returns an http request listener that serves files from `root` on disk.
11|export function serveStatic(root) {
12|  return async (req, res) => {
13|    let path;
14|    try {
15|      path = decodeURIComponent(new URL(req.url, 'http://x').pathname);
16|    } catch {
17|      return res.writeHead(400).end();
18|    }
19|    const file = normalize(join(root, path === '/' ? 'index.html' : path));
20|    if (!file.startsWith(root + sep)) return res.writeHead(403).end(); // path traversal
21|    try {
22|      const body = await readFile(file);
23|      res.writeHead(200, { 'content-type': TYPES[extname(file)] ?? 'application/octet-stream', 'cache-control': 'no-store' });
24|      res.end(body);
25|    } catch {
26|      res.writeHead(404).end('Not found');
27|    }
28|  };
